import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.CQdiwDJy.js";const u=JSON.parse('{"title":"Single-round Q&A (tau ask)","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/ask.md","filePath":"en/guide/ask.md","lastUpdated":1788601681000}'),i={name:"en/guide/ask.md"};function o(r,e,d,l,h,c){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="single-round-q-a-tau-ask" tabindex="-1">Single-round Q&amp;A (tau ask) <a class="header-anchor" href="#single-round-q-a-tau-ask" aria-label="Permalink to &quot;Single-round Q&amp;A (tau ask)&quot;">​</a></h1><p><code>tau ask</code> is Tau&#39;s historical front door: one intent in, one plan, one execution, one result out. It fits tasks that complete in a single step or a fixed sequence — &quot;find this&quot;, &quot;look that up&quot;, &quot;read this file&quot;.</p><h2 id="basic-usage" tabindex="-1">Basic usage <a class="header-anchor" href="#basic-usage" aria-label="Permalink to &quot;Basic usage&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tau</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;find log files larger than 1MB&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tau</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;read package.json and summarize the dependencies&quot;</span></span></code></pre></div><p>You will see the AI&#39;s planning explanation, every step (tool or shell command), the deterministic review verdict, and a confirmation request (low-risk read-only plans can skip interaction with <code>--yes</code>).</p><h2 id="streaming-thinking-v0-5-0" tabindex="-1">Streaming thinking (v0.5.0) <a class="header-anchor" href="#streaming-thinking-v0-5-0" aria-label="Permalink to &quot;Streaming thinking (v0.5.0)&quot;">​</a></h2><p>Since v0.5.0, the planning turn can stream the provider&#39;s thinking as it happens (reasoning deltas): DeepSeek&#39;s <code>reasoning_content</code>, Anthropic&#39;s <code>thinking_delta</code> and Gemini&#39;s thought parts arrive on a separate channel from the plan text. The assembled plan still passes the exact same strict-JSON validation and deterministic review as buffered mode — streaming changes when you see things, never what can execute.</p><p>This capability currently surfaces in the <strong>WebUI</strong>: while planning, thinking streams live into the collapsible panel at the top of the plan card. The CLI does not expose a <code>--stream</code> flag yet — the library APIs (<code>planIntentStream</code> / <code>onPlanStream</code>) are ready for custom integrations.</p><h2 id="context-and-attachments-v0-6-0-library-layer" tabindex="-1">Context and attachments (v0.6.0 library layer) <a class="header-anchor" href="#context-and-attachments-v0-6-0-library-layer" aria-label="Permalink to &quot;Context and attachments (v0.6.0 library layer)&quot;">​</a></h2><p>Since v0.6.0 the planning pipeline natively carries two kinds of context: <strong>conversation history</strong> (<code>priorTurns</code>, folded into the planning intent) and <strong>image attachments</strong> (<code>attachments</code>, native wire shapes for vision providers, an honest annotation for text-only ones). <code>tau ask</code> itself stays single-turn text-only — both contexts are surfaced by the WebUI&#39;s threads and composer attachments; library consumers can pass them directly via <code>planIntent()</code> options (<code>priorTurns</code> / <code>attachments</code>).</p><h2 id="tau-ask-vs-tau-goal" tabindex="-1">tau ask vs tau goal <a class="header-anchor" href="#tau-ask-vs-tau-goal" aria-label="Permalink to &quot;tau ask vs tau goal&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>tau ask</th><th>tau goal</th></tr></thead><tbody><tr><td>Rounds</td><td>1</td><td>up to 5 (default 3)</td></tr><tr><td>Reflection</td><td>none</td><td>provider decides after each round</td></tr><tr><td>Best for</td><td>clear single-step tasks</td><td>tasks that adapt to their own results</td></tr></tbody></table><p><code>tau ask</code> ends when the execution ends. If the provider thinks another round would help, that is <a href="/Tau/en/guide/goal.html">tau goal</a>&#39;s job.</p><h2 id="exit-codes-and-pipes" tabindex="-1">Exit codes and pipes <a class="header-anchor" href="#exit-codes-and-pipes" aria-label="Permalink to &quot;Exit codes and pipes&quot;">​</a></h2><p><code>tau ask</code> follows Unix conventions: 0 on success, non-zero on failure, results on stdout, logs on stderr — ready for pipes and CI scripts.</p>`,15)])])}const g=t(i,[["render",o]]);export{u as __pageData,g as default};
